css:
body > div { width:100%; min-width:0; max-width:100vw; }
.shell .topbar { flex-wrap:wrap; gap:8px; }
.shell .brand { margin-right:0; }
.shell .topbar > .spacer { display:block; flex:1; min-width:80px; min-height:40px; }
.shell .tabs { order:2; flex:1 1 100%; flex-wrap:wrap; justify-content:center; overflow:visible; border-radius:6px; }
.shell .tab { padding:6px 10px; }
.shell .content { min-width:0; }
